    const C = { ...{ gscOn: true, gscProperty: '', gscRange: 28, gscCountry: '', gscAutoSitemap: true, gscCacheHours: 6, gaOn: false, gaId: '', gaReportsOn: true, gaProperty: '', gaConsent: 'banner', gaAds: false, gaExcludeStaff: true, gaEvents: true, gaDebug: false, gaRange: 28, gaCacheHours: 3, psiOn: true, psiUrls: ['/', '/laws', '/laws/civil', '/articles', '/forms/rent-home'], psiStrategy: 'both', psiSchedule: 'weekly', psiAlert: 70, trendsOn: true, trendsKeywords: ['قانون العمل', 'عقد ايجار', 'الطلاق', 'النفقة', 'محامي', 'قانون المرور', 'الضمان الاجتماعي', 'قانون العقوبات'], trendsGeo: 'IQ', trendsTime: 'today 12-m', trendsCat: '0', trendsEmbed: true }, ...(cms.gtools || {}), ...((st0 && st0.cfg) || {}) };
